import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Визиты и магазин","description":"","frontmatter":{"pageId":"players/visits","contentRevision":1},"headers":[],"relativePath":"ru/players/visits.md","filePath":"ru/players/visits.md"}'),s={name:"ru/players/visits.md"};function l(o,a,n,d,p,h){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="визиты-и-магазин" tabindex="-1">Визиты и магазин <a class="header-anchor" href="#визиты-и-магазин" aria-label="Permalink to &quot;Визиты и магазин&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Выбери посещение поселения с карты, через караван или доступную кнопку. В обычном визите загружается копия чужой карты, а не текущая авторитетная симуляция хозяина. Гостевые пешки остаются гостевыми; используй кнопку завершения визита для возвращения.</p><p>Обычные вещи из посещённой копии нельзя просто забрать домой. Разрешённый обмен идёт через магазин хозяина и серверные операции: покупка оплачивается кошельком и учитывается отдельно от состояния копии.</p><p>Если нужен совместный бой в реальном времени, выбирай live-визит и дождись согласия хозяина. Это другой режим с другим протоколом возврата и подключения.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию визит ограничен 12 часами. Не подменяй домашний сейв посещённой копией. Блокировка сообщений сама по себе не запрещает посещение.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: живая карта</a></li><li><a href="./economy">Кошелёк, почта и рынок</a></li><li><a href="./saves-recovery">Сохранения и восстановление</a></li></ul>',10)])])}const _=e(s,[["render",l]]);export{u as __pageData,_ as default};
